def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after +)
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split into core version and pre-release
        if '-' in v_no_build:
            core, prerelease = v_no_build.split('-', 1)
        else:
            core = v_no_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def prerelease_key(prerelease_parts):
        # A version without pre-release sorts after one with pre-release
        # So we use a tuple where (False, ...) comes before (True, ...)
        if prerelease_parts is None:
            # No pre-release: sorts after any pre-release
            return (False, [])

        # Convert pre-release parts to comparable format
        converted = []
        for part in prerelease_parts:
            if part.isdigit():
                # All-digit identifier: (0, numeric_value)
                converted.append((0, int(part)))
            else:
                # Non-digit identifier: (1, string_value)
                converted.append((1, part))

        return (True, converted)

    def compare_key(v):
        major, minor, patch, prerelease_parts = parse_version(v)
        pre_key = prerelease_key(prerelease_parts)
        return (major, minor, patch, pre_key)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

